// Sample input. Replace with the real session facts you want to hand off.
return [{ json: {
  goal: 'Add OAuth login to the dashboard and cover it with tests',
  current_state: 'Login route works; token refresh is flaky under load',
  files_touched: ['src/auth/oauth.ts', 'src/routes/login.ts', 'tests/auth.test.ts'],
  what_changed: ['Added oauth.ts provider wrapper', 'Wired /login to provider', 'Added 4 happy-path tests'],
  what_failed: ['Token refresh test intermittently times out', 'No test yet for expired refresh token'],
  next_steps: ['Reproduce refresh timeout with a fixed clock', 'Add expired-token test', 'Review error handling in oauth.ts'],
  output_path: './handoff.md'
} }];

const md = [];
const j = $input.first().json;
const e = [];
const reqStr = ['goal', 'current_state'];
for (const k of reqStr) if (typeof j[k] !== 'string' || !j[k].trim()) e.push(k + ' is required');
const reqArr = ['files_touched', 'what_changed', 'what_failed', 'next_steps'];
for (const k of reqArr) if (!Array.isArray(j[k])) e.push(k + ' must be an array');
if (e.length) throw new Error('Invalid input: ' + e.join('; '));
const list = a => (a.length ? a.map(x => '- ' + x).join('\n') : '- (none)');
md.push('# Session handoff');
md.push('');
md.push('_Generated ' + new Date().toISOString() + '_');
md.push('');
md.push('## Goal');
md.push(j.goal);
md.push('');
md.push('## Current state');
md.push(j.current_state);
md.push('');
md.push('## Files touched');
md.push(list(j.files_touched));
md.push('');
md.push('## What changed');
md.push(list(j.what_changed));
md.push('');
md.push('## What failed');
md.push(list(j.what_failed));
md.push('');
md.push('## What to do next');
md.push(list(j.next_steps));
md.push('');
md.push('---');
md.push('Start a fresh session (/clear or new) and instruct it: "Read handoff.md and continue exactly where the last session left off."');
return [{ json: { output_path: j.output_path || './handoff.md', markdown: md.join('\n') } }];
